         const blush=Math.exp(-((gx-cx)**2/180+(gy-cy)**2/110))*.36;d[k]=mix(d[k],255,blush);d[k+1]=mix(d[k+1],124,blush);d[k+2]=mix(d[k+2],178,blush)
